import requests

def find_servers(registry_url, capability):
    response = requests.get(
        f"{registry_url}/servers",
        params={"capability": capability}
    )
    response.raise_for_status()
    return response.json()["servers"]

candidates = find_servers("https://registry.example.com", "currency-conversion")
for server in candidates:
    print(server["name"], server["endpoint"], server["lastSeen"])

async function findTrustedServers(registryUrl, capability) {
  const res = await fetch(
    `${registryUrl}/servers?capability=${capability}`
  );
  const { servers } = await res.json();
  const freshCutoff = Date.now() - 5 * 60 * 1000;
  return servers.filter(
    (s) => s.signed === true && new Date(s.lastSeen).getTime() > freshCutoff
  );
}
